      "The river pathway is historical fact, not merely a proximity concern. EPA's remedial investigation identified groundwater discharge from landfill fill and alluvium into the embayment as the principal off-site migration route, and sediment contamination extended to an area within roughly 300 feet of shore. Contemporary reporting in 1993 recorded health officials warning about substances still leaking into the river while the final remedy was being designed.",
      "Later monitoring documents a changed condition. EPA's May 2026 five-year review retained the 2017 conclusion that site-related contamination was not migrating toward the Niagara River, while continuing to find stable residual contamination in several monitoring wells outside the slurry wall. The historical release and the current containment finding belong in the same story, each labeled by date.",
