      "DEC's 2021 work plan recorded occasional exposed waste along the tributary bank and pooled leachate near the boat launch. Five wells and one seep were sampled in March 2022 under the state's Inactive Landfill Initiative; fill containing glass, metal, cloth, brick, cinder, and wood extended roughly 5 to 17 feet below ground in the five borings.",
      "Orange-red seeps near the launch have been reported repeatedly since at least 2003. The appearance prompted new public concern in 2024 and 2026. DEC attributes the material to iron-rich groundwater reaching the surface through poorly drained ground, where naturally occurring bacteria oxidize the dissolved iron.",
